    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
    @Mapping(target = "riskFlag", expression = "java(resolveRiskFlag(owner))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

